	LoggerFactory.setLogBackendFactory(ourLogFactory);

	String message = "hello";
	expect(log.isLevelEnabled(Level.INFO)).andReturn(true);
	log.log(Level.INFO, message);

	replay(log);
	Logger logger = LoggerFactory.getLogger("test");
	logger.info(message);
	verify(log);
}

